<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$pdo=db();$impact=donor_impact($pdo,(int)$user['id']);$winter=$pdo->prepare("SELECT COALESCE(SUM(di.quantity),0) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id JOIN clothing_requests cr ON cr.id=dp.request_id WHERE dp.donor_id=? AND dp.status='received' AND cr.season='Winter'");$winter->execute([$user['id']]);$metrics=['completed_donations'=>$impact['donations'],'items_donated'=>$impact['items'],'winter_items'=>$winter->fetchColumn()];$stmt=$pdo->prepare('SELECT a.*,ua.earned_at FROM achievements a LEFT JOIN user_achievements ua ON ua.achievement_id=a.id AND ua.user_id=? WHERE a.is_active=1 ORDER BY a.target_value');$stmt->execute([$user['id']]);$badges=$stmt->fetchAll();$pageTitle='Your achievements';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="subnav"><a href="<?=e(url('donor/dashboard.php'))?>">Dashboard</a><a href="<?=e(url('donor/matcher.php'))?>">Smart matcher</a><a href="<?=e(url('donor/passport.php'))?>">Passport</a><a class="is-active" href="<?=e(url('donor/achievements.php'))?>">Achievements</a><a href="<?=e(url('donor/leaderboard.php'))?>">Leaderboard</a></div><div class="welcome-row"><div><span class="eyebrow">Celebrate real impact</span><h1>Achievements</h1><p>Badges unlock only after a charity confirms the donation has arrived.</p></div></div><div class="achievement-grid"><?php foreach($badges as $badge):$value=(int)($metrics[$badge['metric']]??0);$percent=min(100,(int)round($value/(int)$badge['target_value']*100));?><article class="achievement-card <?=$badge['earned_at']?'earned':''?>"><span class="achievement-icon"><?=e($badge['icon'])?></span><h3><?=e($badge['name'])?></h3><p><?=e($badge['description'])?></p><div class="achievement-progress"><span style="width:<?=$percent?>%"></span></div><small class="muted"><?=$badge['earned_at']?'Unlocked '.format_date($badge['earned_at']):$value.' / '.$badge['target_value'].' progress'?></small></article><?php endforeach;?></div></div></section>
